from pathlib import Path
import numpy as np, h5py
from scipy.io import loadmat

root = Path('/app/data')

def parse_subject(path):
    return path.stem.split('_')[2]

def count_neurons_scipy(clu):
    n_neurons = 0
    probes = clu if isinstance(clu, (list, tuple, np.ndarray)) else [clu]
    for idx, probe in enumerate(probes):
        if probe is None:
            continue
        if isinstance(probe, dict) and 'quality' in probe:
            q = probe['quality']
            if isinstance(q, list):
                n_neurons += len(q)
            else:
                arr = np.asarray(q)
                if arr.ndim == 0:
                    n_neurons += 1
                else:
                    n_neurons += int(arr.shape[0])
    return n_neurons

for path in sorted(root.glob('*/*.mat')):
    if not path.name.startswith('data_structure_'):
        continue
    try:
        try:
            with h5py.File(path, 'r') as h:
                ntrials = int(round(float(h['obj']['bp']['Ntrials'][()][0,0])))
                n_neurons = 0
                if 'clu' in h['obj']:
                    refs = h['obj']['clu'][:]
                    for i in range(refs.shape[0]):
                        target = h[refs[i,0]]
                        if isinstance(target, h5py.Group) and 'quality' in target:
                            n_neurons += int(target['quality'].shape[0])
                fmt='hdf5'
        except OSError:
