import os, re, json, math
from pathlib import Path
import numpy as np
import scipy.io
import mat73

DATA=Path('/app/data')
folders=['Ephys_Behavior','RandomizedDelay_Ephys_Behavior']

def load_session(path):
    try:
        d=mat73.loadmat(str(path))
        return d['obj'],'mat73'
    except Exception:
        d=scipy.io.loadmat(str(path), simplify_cells=True)
        return d['obj'],'scipy'

def get_field(obj, name, default=None):
    if isinstance(obj, dict):
        return obj.get(name, default)
    if hasattr(obj, name):
        return getattr(obj, name)
    return default

rows=[]
for folder in folders:
    for path in sorted((DATA/folder).glob('data_structure_*.mat')):
        obj,_=load_session(path)
        bp=get_field(obj,'bp',{})
        clu=get_field(obj,'clu',None)
        if clu is None:
            continue
        N=int(get_field(bp,'Ntrials',0) or 0)
        def arr(name):
            x=get_field(bp,name,None)
            if x is None:
                return np.zeros(N,dtype=bool)
            return np.asarray(x).astype(bool)
        autowater=arr('autowater')
        early=arr('early')
        stim=arr('stim')
        hit=arr('hit')
        miss=arr('miss')
        no=arr('no')
        protocol=get_field(bp,'protocol',None)
        if isinstance(protocol, (list, tuple, np.ndarray)):
            prot=';'.join(map(str,np.ravel(protocol)[:5]))
        else:
            prot=str(protocol)
        mouse=path.stem.split('_')[2]
        date=path.stem.split('_')[3]
        rows.append({
            'folder':folder,
            'mouse':mouse,
            'date':date,
            'trials':N,
            'wc_trials':int(autowater.sum()),
            'dr_trials':int((~autowater).sum()),
            'early':int(early.sum()),
            'stim':int(stim.sum()),
            'hit':int(hit.sum()),
            'miss':int(miss.sum()),
            'no':int(no.sum()),
            'protocol':prot,
        })

# summarize
print('NEURAL_SESSIONS', len(rows))
print('WC_SESSION_COUNT', sum(r['wc_trials']>0 for r in rows))
print('RANDOMIZED_FOLDER_SESSIONS', sum(r['folder']=='RandomizedDelay_Ephys_Behavior' for r in rows))
print('FIXED_FOLDER_SESSIONS', sum(r['folder']=='Ephys_Behavior' for r in rows))
print('WC_SESSIONS:')
for r in rows:
    if r['wc_trials']>0:
        print(r['mouse'], r['date'], r['folder'], 'wc', r['wc_trials'], 'dr', r['dr_trials'], 'protocol', r['protocol'])
