        for probe in as_list(clu):
            q=gf(probe,'quality',None)
            if q is None: continue
            for item in as_list(q):
                s=str(item)
                ctr[s]+=1
                examples.setdefault(s, path.name)
print('UNIQUE_QUALITIES', len(ctr))
for k,v in ctr.most_common():
