from pathlib import Path
import re, collections, numpy as np, scipy.io, mat73, sys
base=Path('/app/code/DataLoadingScripts/Recording and video')
cohorts={
 'fixed':['JEB6','JEB7','EKH1','EKH3','JGR2','JGR3','JEB13','JEB14','JEB15','JEB19'],
 'randomized':['JEB11','JEB12','JEB23','JEB24'],
}

def parse_sessions(animals):
    sessions=[]
    for animal in animals:
        txt=(base/f'load{animal}_ALMVideo.m').read_text(errors='ignore')
        current=None
        for line in txt.splitlines():
            s=line.strip()
            if s.startswith('%'): continue
            m=re.search(r"date = '([^']+)'", s)
            if m: current=m.group(1)
            m2=re.search(r'probe = (\[[^\]]+\]|\d+);', s)
            if m2 and current:
                probe_text=m2.group(1)
                probe=[int(x) for x in re.findall(r'\d+', probe_text)]
                sessions.append((animal,current,probe))
                current=None
    return sessions

def load_session(path):
    try:
        return mat73.loadmat(str(path))['obj']
    except Exception:
        return scipy.io.loadmat(str(path), simplify_cells=True)['obj']

def gf(obj,name,default=None):
    if isinstance(obj,dict): return obj.get(name,default)
    return getattr(obj,name,default)

def as_list(x):
    if x is None: return []
    if isinstance(x,list): return x
    if isinstance(x,tuple): return list(x)
    if isinstance(x,np.ndarray):
        if x.dtype==object: return list(x.ravel())
        return list(x)
    return [x]

def normalize_quality(q):
    if q is None: return ''
    s=str(q).strip()
    return s
bad={'garbage','gabrga','noisy','real?'}
for cname, animals in cohorts.items():
    sessions=parse_sessions(animals)
    counts=collections.Counter()
    total_selected=0
    total_findclusters=0
    print('COHORT', cname, 'sessions', len(sessions), flush=True)
    for animal,date,probes in sessions:
        path=Path('/app/data')/('RandomizedDelay_Ephys_Behavior' if cname=='randomized' else 'Ephys_Behavior')/f'data_structure_{animal}_{date}.mat'
        obj=load_session(path)
        clu=as_list(gf(obj,'clu'))
        sess_sel=0
        sess_keep=0
        for p in probes:
            probe=clu[p-1]
            qlist=as_list(gf(probe,'quality'))
            sess_sel += len(qlist)
            sess_keep += sum(normalize_quality(q) not in bad for q in qlist)
            for q in qlist:
