        total_selected += sess_sel
        total_findclusters += sess_keep
        print(animal, date, probes, 'selected', sess_sel, 'findClusters_all', sess_keep, flush=True)
    print('TOTAL_SELECTED', total_selected)
    print('TOTAL_FINDCLUSTERS_ALL', total_findclusters)
    print('QUALITIES')
    for k,v in counts.most_common():
        print(repr(k), v)
