from pathlib import Path
import re, numpy as np, scipy.io, mat73
base=Path('/app/code/DataLoadingScripts/Recording and video')
cohorts={
 'fixed':['JEB6','JEB7','EKH1','EKH3','JGR2','JGR3','JEB13','JEB14','JEB15','JEB19'],
 'randomized':['JEB11','JEB12','JEB23','JEB24'],
}

def parse_sessions(animals):
    out=[]
    for animal in animals:
        txt=(base/f'load{animal}_ALMVideo.m').read_text(errors='ignore')
        current=None
        for line in txt.splitlines():
            s=line.strip()
            if s.startswith('%'): continue
            m=re.search(r"date = '([^']+)'", s)
            if m: current=m.group(1)
            m2=re.search(r'probe = (\[[^\]]+\]|\d+);', s)
            if m2 and current:
                probes=[int(x) for x in re.findall(r'\d+', m2.group(1))]
                out.append((animal,current,probes))
                current=None
    return out

def load(path):
    try:
        return mat73.loadmat(str(path))['obj'], 'mat73'
    except Exception:
        return scipy.io.loadmat(str(path), simplify_cells=True)['obj'], 'scipy'

def gf(obj,name,default=None):
    if isinstance(obj,dict): return obj.get(name,default)
    return getattr(obj,name,default)

def is_flat_unit_list(clu):
    return isinstance(clu,list) and clu and isinstance(clu[0],dict) and 'tm' in clu[0] and 'quality' in clu[0]

def probe_quality_lists(obj, selected_probes):
    clu=gf(obj,'clu')
    if is_flat_unit_list(clu):
        # older files already store a single selected probe as a flat unit list
        return [ [u.get('quality','') for u in clu] ]
    if isinstance(clu, dict):
        return [ list(np.ravel(gf(clu,'quality',[]))) ]
    if isinstance(clu, list):
        out=[]
        for p in selected_probes:
            probe=clu[p-1]
            q=gf(probe,'quality',[])
            if isinstance(q, np.ndarray):
                out.append(list(np.ravel(q)))
            elif isinstance(q, list):
                out.append(q)
            else:
                out.append([q])
        return out
    raise TypeError(type(clu))

bad={'garbage','gabrga','noisy','real?'}
for cname, animals in cohorts.items():
    total=0; keep=0
    print('COHORT', cname)
    for animal,date,probes in parse_sessions(animals):
        folder='RandomizedDelay_Ephys_Behavior' if cname=='randomized' else 'Ephys_Behavior'
        obj,src=load(Path('/app/data')/folder/f'data_structure_{animal}_{date}.mat')
        qlists=probe_quality_lists(obj, probes)
        sess_total=sum(len(qs) for qs in qlists)
        sess_keep=sum(sum(str(q).strip() not in bad for q in qs) for qs in qlists)
        total += sess_total; keep += sess_keep
        print(animal,date,src,probes,'total',sess_total,'keep',sess_keep)
    print('TOTAL', total, 'KEEP', keep)
