from pathlib import Path
import re, numpy as np, scipy.io, mat73
base=Path('/app/code/DataLoadingScripts/Recording and video')
animals=['JEB6','JEB7','EKH1','EKH3','JGR2','JGR3','JEB19','JEB13','JEB14','JEB15','JEB11','JEB12','JEB23','JEB24']
sessions=[]
for animal in animals:
    txt=(base/f'load{animal}_ALMVideo.m').read_text(errors='ignore')
    current=None
    for line in txt.splitlines():
        s=line.strip()
        if s.startswith('%'): continue
        m=re.search(r"date = '([^']+)'", s)
        if m: current=m.group(1)
        m2=re.search(r'probe = (\[[^\]]+\]|\d+);', s)
        if m2 and current:
            sessions.append((animal,current,'RandomizedDelay_Ephys_Behavior' if animal in {'JEB11','JEB12','JEB23','JEB24'} else 'Ephys_Behavior'))
            current=None

def load(path):
    try:
        return mat73.loadmat(str(path))['obj']
    except Exception:
        return scipy.io.loadmat(str(path), simplify_cells=True)['obj']

def gf(obj,name,default=None):
    if isinstance(obj,dict): return obj.get(name,default)
    return getattr(obj,name,default)

any_aw=[]
for animal,date,folder in sessions:
    obj=load(Path('/app/data')/folder/f'data_structure_{animal}_{date}.mat')
    bp=gf(obj,'bp')
    N=int(gf(bp,'Ntrials',0) or 0)
    aw=np.asarray(gf(bp,'autowater',np.zeros(N))).astype(bool)
    any_aw.append((animal,date,folder,int(aw.sum())))
print('SESSIONS_WITH_AW', sum(v>0 for *_,v in any_aw), 'of', len(any_aw))
for row in any_aw:
    if row[-1]>0:
        print(row)
