# summarize stim/early/no counts for candidate neural cohort
animals=['JEB6','JEB7','EKH1','EKH3','JGR2','JGR3','JEB19','JEB13','JEB14','JEB15','JEB11','JEB12','JEB23','JEB24']
sessions=[]
for animal in animals:
    txt=(base/f'load{animal}_ALMVideo.m').read_text(errors='ignore')
    current=None
    for line in txt.splitlines():
        s=line.strip()
        if s.startswith('%'): continue
        m=re.search(r"date = '([^']+)'", s)
        if m: current=m.group(1)
        m2=re.search(r'probe = (\[[^\]]+\]|\d+);', s)
        if m2 and current:
            sessions.append((animal,current,'RandomizedDelay_Ephys_Behavior' if animal in {'JEB11','JEB12','JEB23','JEB24'} else 'Ephys_Behavior'))
            current=None

def load(path):
    try:
        return mat73.loadmat(str(path))['obj']
    except Exception:
        return scipy.io.loadmat(str(path), simplify_cells=True)['obj']

def gf(obj,name,default=None):
    if isinstance(obj,dict): return obj.get(name,default)
    return getattr(obj,name,default)

sums={'trials':0,'early':0,'stim':0,'ignore':0,'hit':0,'miss':0,'aw':0}
for animal,date,folder in sessions:
    obj=load(Path('/app/data')/folder/f'data_structure_{animal}_{date}.mat')
    bp=gf(obj,'bp')
    N=int(gf(bp,'Ntrials',0) or 0)
    stimfield=gf(bp,'stim',None)
    if isinstance(stimfield,dict): stim=np.asarray(stimfield.get('enable',np.zeros(N))).astype(bool)
    elif hasattr(stimfield,'enable'): stim=np.asarray(stimfield.enable).astype(bool)
    else: stim=np.zeros(N,dtype=bool)
    early=np.asarray(gf(bp,'early',np.zeros(N))).astype(bool)
    no=np.asarray(gf(bp,'no',np.zeros(N))).astype(bool)
    hit=np.asarray(gf(bp,'hit',np.zeros(N))).astype(bool)
    miss=np.asarray(gf(bp,'miss',np.zeros(N))).astype(bool)
    aw=np.asarray(gf(bp,'autowater',np.zeros(N))).astype(bool)
    sums['trials'] += N; sums['early'] += int(early.sum()); sums['stim'] += int(stim.sum()); sums['ignore'] += int(no.sum()); sums['hit'] += int(hit.sum()); sums['miss'] += int(miss.sum()); sums['aw'] += int(aw.sum())
print(sums)
