from pathlib import Path
import scipy.io, mat73, numpy as np
path=Path('/app/data/Ephys_Behavior/data_structure_JEB6_2021-04-18.mat')
try:
    obj=mat73.loadmat(str(path))['obj']
except Exception:
    obj=scipy.io.loadmat(str(path), simplify_cells=True)['obj']
bp=obj['bp'] if isinstance(obj,dict) else obj.bp
ev=bp['ev'] if isinstance(bp,dict) else bp.ev
L=np.asarray(bp['L'] if isinstance(bp,dict) else bp.L).astype(bool)
hit=np.asarray(bp['hit'] if isinstance(bp,dict) else bp.hit).astype(bool)
miss=np.asarray(bp['miss'] if isinstance(bp,dict) else bp.miss).astype(bool)
no=np.asarray(bp['no'] if isinstance(bp,dict) else bp.no).astype(bool)
go=np.asarray(ev['goCue'] if isinstance(ev,dict) else ev.goCue)
lickL=ev['lickL'] if isinstance(ev,dict) else ev.lickL
lickR=ev['lickR'] if isinstance(ev,dict) else ev.lickR

def arr(x):
    if x is None:
        return np.array([])
    a=np.array(x, dtype=object).reshape(-1)
    vals=[]
    for v in a:
        if v is None:
            continue
        try:
            vals.append(float(v))
        except Exception:
            pass
    return np.array(vals, dtype=float)

def actual_choice(tr):
    left=arr(lickL[tr]); right=arr(lickR[tr])
    left=left[left>go[tr]]; right=right[right>go[tr]]
    tL=left.min() if left.size else np.inf
    tR=right.min() if right.size else np.inf
    if np.isinf(tL) and np.isinf(tR):
        return 'none'
    return 'left' if tL < tR else 'right'

for tr in range(20):
    print(tr+1, 'L' if L[tr] else 'R', 'hit' if hit[tr] else 'miss' if miss[tr] else 'no', actual_choice(tr))
